"use client";

import { useEffect, useMemo, useState } from "react";
import { useRouter, useSearchParams } from "next/navigation";
import {
  Car,
  CheckCircle2,
  ChevronRight,
  Dumbbell,
  Flower2,
  Heart,
  List,
  Map as MapIcon,
  MapPin,
  Snowflake,
  Star,
  Umbrella,
  Utensils,
  Waves,
  Wifi,
  Wine,
  type LucideIcon,
} from "lucide-react";
import {
  ApiError,
  getHotelDetails,
  getHotels,
  type HotelSearchPayload,
} from "@/services/hotels.service";
import { geocodeText, type Coords } from "@/lib/geocode";
import styles from "./hotel-list.module.css";

const IMAGE_BASE = (
  process.env.NEXT_PUBLIC_HOTEL_IMAGE_BASE ??
  "https://photos.hotelbeds.com/giata/bigger/"
).replace(/\/*$/, "/");
const FALLBACK_IMAGE = "/images/img-placeholder.png"; // put a file at public/images/img-placeholder.png
const DETAILS_BATCH = 50;
const STEP = 5; // price slider step

/** Same values as the Postman request. */
const SHIFT_DAYS = 1;
const ALLOW_ONLY_SHIFT = true;
const DEFAULT_RADIUS = "20";
const DEFAULT_UNIT = "km";
const DEFAULT_CHILD_AGE = 8;

// ==========================================================
// Static lookups
// ==========================================================

/** Hotelbeds accommodationTypeCode -> label. Add more if one looks off. */
const TYPE_LABELS: Record<string, string> = {
  HOTEL: "Hotels",
  RESORT: "Resorts",
  VILLA: "Villas",
  APART: "Apartments",
  APARTMENT: "Apartments",
  APTHOTEL: "Apartments",
  HOSTEL: "Hostels",
  BB: "B&Bs",
  HOMES: "Homes",
};

/** Sidebar "Popular Facilities" (matched against facility names). */
const FACILITY_FILTERS = [
  { key: "wifi", label: "Free WiFi", test: /wi-?fi|internet/ },
  { key: "pool", label: "Swimming Pool", test: /pool/ },
  { key: "breakfast", label: "Breakfast Included", test: /breakfast/ },
  { key: "seaview", label: "Sea View", test: /sea view|ocean view/ },
  { key: "airport", label: "Airport Transfer", test: /airport/ },
];

/** Icons shown on each card (first 4 that match). */
const AMENITY_RULES: { label: string; test: RegExp; Icon: LucideIcon }[] = [
  { label: "Beach", test: /beach/, Icon: Umbrella },
  { label: "Pool", test: /pool/, Icon: Waves },
  { label: "Spa", test: /\bspa\b|wellness|massage/, Icon: Flower2 },
  { label: "Free WiFi", test: /wi-?fi|internet/, Icon: Wifi },
  { label: "Restaurant", test: /restaurant/, Icon: Utensils },
  { label: "Gym", test: /gym|fitness/, Icon: Dumbbell },
  { label: "Parking", test: /parking/, Icon: Car },
  { label: "Air conditioning", test: /air conditioning/, Icon: Snowflake },
  { label: "Bar", test: /\bbar\b/, Icon: Wine },
];

type Amenity = { label: string; Icon: LucideIcon };

interface HotelCardData {
  code: number;
  name: string;
  stars: number;
  destination: string;
  address: string;
  price: number | null; // total for the stay
  perNight: number | null;
  currency: string;
  images: string[];
  description: string;
  rating: number | null; // 0-10
  reviewCount: number | null;
  type: string | null;
  amenities: Amenity[];
  facilityKeys: string[];
}

type Sort = "recommended" | "priceLow" | "priceHigh" | "rating" | "stars";

// ==========================================================
// Response helpers
// ==========================================================

/** Hotels array from an availability response. */
function pickHotels(res: any): any[] {
  const candidates = [
    res?.data?.hotels?.hotels,
    res?.data?.hotels,
    res?.hotels?.hotels,
    res?.hotels,
    res?.data,
    res,
  ];
  return candidates.find(Array.isArray) ?? [];
}

/** Hotel content from a details response (array or single hotel object). */
function pickDetails(res: any): any[] {
  const arr = [
    res?.data?.hotels?.hotels,
    res?.data?.hotels,
    res?.hotels?.hotels,
    res?.hotels,
  ].find(Array.isArray);
  if (arr) return arr;

  const single = [res?.data?.hotel, res?.hotel].find(
    (h) => h && typeof h === "object" && !Array.isArray(h),
  );
  return single ? [single] : [];
}

function starsFrom(raw: any): number {
  const m = String(raw ?? "").match(/(\d)/);
  return m ? Number(m[1]) : 0;
}

/** Reads strings or { content: "..." } objects. */
function text(v: any): string {
  if (v == null) return "";
  if (typeof v === "string") return v;
  return v.content ?? v.description?.content ?? v.description ?? v.name ?? "";
}

function toImageUrl(raw: string): string {
  if (raw.startsWith("http") || raw.startsWith("//")) return raw;
  return IMAGE_BASE + raw.replace(/^\/+/, "");
}

/** All images: general photo first, then by visualOrder. */
function pickImages(d: any, h: any): string[] {
  const list: any[] = Array.isArray(d?.images) ? [...d.images] : [];
  list.sort(
    (a, b) =>
      (a?.type?.code === "GEN" ? 0 : 1) - (b?.type?.code === "GEN" ? 0 : 1) ||
      (a?.visualOrder ?? a?.order ?? 999) - (b?.visualOrder ?? b?.order ?? 999),
  );

  const raws = list
    .map((i) => (typeof i === "string" ? i : (i?.path ?? i?.url)))
    .filter((p): p is string => typeof p === "string" && !!p);

  if (!raws.length) {
    const r = h?.image ?? h?.thumbnail;
    if (typeof r === "string" && r) raws.push(r);
  }

  return raws.map(toImageUrl);
}

/** All facility names. Skips facilities the hotel does NOT offer (indLogic === false). */
function pickFacilities(d: any): string[] {
  const out: string[] = [];
  for (const f of d?.facilities ?? []) {
    if (f?.indLogic === false) continue;
    const name =
      (typeof f === "string" ? f : "") ||
      text(f?.description) ||
      text(f?.name) ||
      "";
    const clean = String(name).trim();
    if (clean && !out.includes(clean)) out.push(clean);
  }
  return out;
}

function pickAmenities(names: string[], joined: string): Amenity[] {
  const matched = AMENITY_RULES.filter((r) => r.test.test(joined))
    .slice(0, 4)
    .map((r) => ({ label: r.label, Icon: r.Icon }));

  if (matched.length) return matched;

  return names.slice(0, 4).map((n) => ({ label: n, Icon: CheckCircle2 }));
}

function typeLabel(code: any): string | null {
  const c = String(code ?? "").trim().toUpperCase();
  if (!c) return null;
  return TYPE_LABELS[c] ?? c.charAt(0) + c.slice(1).toLowerCase();
}

/** Rating on a 10-point scale (Hotelbeds reviews are usually out of 5). */
function pickReview(h: any): { rating: number | null; count: number | null } {
  const review = h?.reviews?.[0];
  const rate = review?.rate != null ? Number(review.rate) : NaN;
  const count = review?.reviewCount != null ? Number(review.reviewCount) : NaN;
  const score = Number.isFinite(rate) ? (rate <= 5 ? rate * 2 : rate) : null;

  return {
    rating: score,
    count: Number.isFinite(count) ? count : null,
  };
}

function ratingLabel(score: number): string {
  if (score >= 9.4) return "Exceptional";
  if (score >= 9) return "Superb";
  if (score >= 8) return "Excellent";
  if (score >= 7) return "Very good";
  if (score >= 6) return "Good";
  return "Review score";
}

function normalize(
  av: any,
  details: Map<number, any>,
  nights: number,
): HotelCardData[] {
  const list = pickHotels(av);
  if (!list.length) return [];

  return list.map((h) => {
    const d = details.get(Number(h.code)) ?? {};
    const review = pickReview(h);

    const names = pickFacilities(d);
    const joined = names.join(" | ").toLowerCase();

    const total = h.minRate != null ? Number(h.minRate) : null;
    const hasPrice = total != null && Number.isFinite(total);

    return {
      code: Number(h.code),
      name: text(d.name) || text(h.name) || "Hotel",
      stars: starsFrom(h.categoryName ?? h.categoryCode ?? d.categoryCode),
      destination: h.destinationName ?? text(d.city) ?? "",
      address: text(d.address),
      price: hasPrice ? total : null,
      perNight: hasPrice ? total / nights : null,
      currency: h.currency ?? "USD",
      images: pickImages(d, h),
      description: text(d.description),
      rating: review.rating,
      reviewCount: review.count,
      type: typeLabel(d.accommodationTypeCode),
      amenities: pickAmenities(names, joined),
      facilityKeys: FACILITY_FILTERS.filter((f) => f.test.test(joined)).map(
        (f) => f.key,
      ),
    };
  });
}

// ==========================================================
// Search payload
// ==========================================================

function buildPayload(sp: URLSearchParams, coords: Coords): HotelSearchPayload {
  const rooms = Math.max(1, Number(sp.get("rooms") ?? 1));
  const adults = Math.max(1, Number(sp.get("adults") ?? 2));
  const children = Math.max(0, Number(sp.get("children") ?? 0));

  const given = (sp.get("childAges") ?? "")
    .split(",")
    .map((a) => Number(a))
    .filter((a) => Number.isFinite(a) && a >= 0);

  const paxes = Array.from({ length: children }, (_, i) => ({
    type: "CH" as const,
    age: given[i] ?? DEFAULT_CHILD_AGE,
  }));

  return {
    stay: {
      checkIn: sp.get("checkIn") ?? "",
      checkOut: sp.get("checkOut") ?? "",
      shiftDays: SHIFT_DAYS,
      allowOnlyShift: ALLOW_ONLY_SHIFT,
    },
    occupancies: [{ rooms, adults, children, paxes }],
    geolocation: {
      longitude: String(coords.lng),
      latitude: String(coords.lat),
      radius: sp.get("radius") ?? DEFAULT_RADIUS,
      unit: sp.get("unit") ?? DEFAULT_UNIT,
    },
  };
}

async function resolveCoords(
  sp: URLSearchParams,
  signal: AbortSignal,
): Promise<Coords | null> {
  const lat = Number(sp.get("lat"));
  const lng = Number(sp.get("lng"));

  if (
    sp.get("lat") &&
    sp.get("lng") &&
    Number.isFinite(lat) &&
    Number.isFinite(lng)
  ) {
    return { lat, lng };
  }

  return geocodeText(sp.get("term") ?? "", signal);
}

function nightsBetween(a: string, b: string) {
  const n = Math.round((+new Date(b) - +new Date(a)) / 86400000);
  return Number.isFinite(n) && n > 0 ? n : 1;
}

function money(amount: number, currency: string, digits = 0) {
  try {
    return new Intl.NumberFormat("en-US", {
      style: "currency",
      currency,
      maximumFractionDigits: digits,
    }).format(amount);
  } catch {
    return `${currency} ${amount.toFixed(digits)}`;
  }
}

function toggle<T>(set: Set<T>, value: T): Set<T> {
  const next = new Set(set);
  if (next.has(value)) next.delete(value);
  else next.add(value);
  return next;
}

// ==========================================================
// Small UI pieces
// ==========================================================

/** Photo that always fills its wrapper; falls back to a placeholder. */
function HotelImage({ src, alt }: { src?: string; alt: string }) {
  const [failed, setFailed] = useState(false);

  return (
    <div className={styles.media}>
      {/* eslint-disable-next-line @next/next/no-img-element */}
      <img
        key={src}
        src={failed || !src ? FALLBACK_IMAGE : src}
        alt={alt}
        loading="lazy"
        referrerPolicy="no-referrer"
        onError={() => setFailed(true)}
      />
    </div>
  );
}

/** Two-handle price slider. */
function PriceSlider({
  ceiling,
  lo,
  hi,
  onChange,
}: {
  ceiling: number;
  lo: number;
  hi: number;
  onChange: (lo: number, hi: number) => void;
}) {
  const pct = (v: number) => (v / ceiling) * 100;

  return (
    <div className={styles.slider}>
      <div className={styles.sliderTrack} />
      <div
        className={styles.sliderFill}
        style={{ left: `${pct(lo)}%`, right: `${100 - pct(hi)}%` }}
      />
      <input
        type="range"
        aria-label="Minimum price"
        className={styles.sliderInput}
        style={{ zIndex: lo > ceiling - STEP * 4 ? 5 : 3 }}
        min={0}
        max={ceiling}
        step={STEP}
        value={lo}
        onChange={(e) => onChange(Math.min(Number(e.target.value), hi - STEP), hi)}
      />
      <input
        type="range"
        aria-label="Maximum price"
        className={styles.sliderInput}
        style={{ zIndex: 4 }}
        min={0}
        max={ceiling}
        step={STEP}
        value={hi}
        onChange={(e) => onChange(lo, Math.max(Number(e.target.value), lo + STEP))}
      />
    </div>
  );
}

// ==========================================================
// Component
// ==========================================================

export default function HotelList() {
  const router = useRouter();
  const sp = useSearchParams();
  const spKey = sp.toString();

  const [hotels, setHotels] = useState<HotelCardData[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const [sort, setSort] = useState<Sort>("recommended");
  const [starSel, setStarSel] = useState<Set<number>>(new Set());
  const [typeSel, setTypeSel] = useState<Set<string>>(new Set());
  const [facSel, setFacSel] = useState<Set<string>>(new Set());
  const [range, setRange] = useState<[number, number] | null>(null);
  const [wishlist, setWishlist] = useState<Set<number>>(new Set());

  const resetFilters = () => {
    setStarSel(new Set());
    setTypeSel(new Set());
    setFacSel(new Set());
    setRange(null);
  };

  useEffect(() => {
    const ctrl = new AbortController();
    const params = new URLSearchParams(spKey);
    const stayNights = nightsBetween(
      params.get("checkIn") ?? "",
      params.get("checkOut") ?? "",
    );

    (async () => {
      setLoading(true);
      setError(null);
      setHotels([]);
      resetFilters();

      try {
        if (!params.get("checkIn") || !params.get("checkOut")) {
          throw new Error("Please choose check-in and check-out dates.");
        }

        const coords = await resolveCoords(params, ctrl.signal);
        if (!coords) {
          throw new Error(
            "Couldn't find the location for this search. Please pick a destination from the suggestions.",
          );
        }

        const av = await getHotels(buildPayload(params, coords), ctrl.signal);
        const codes = pickHotels(av).map((h) => Number(h.code));

        // show prices immediately, enrich with content afterwards
        setHotels(normalize(av, new Map(), stayNights));
        setLoading(false);

        const map = new Map<number, any>();
        for (let i = 0; i < codes.length; i += DETAILS_BATCH) {
          try {
            const res = await getHotelDetails(
              codes.slice(i, i + DETAILS_BATCH),
              ctrl.signal,
            );
            pickDetails(res).forEach((d) => map.set(Number(d.code), d));
            setHotels(normalize(av, map, stayNights));
          } catch (err: any) {
            if (err?.name === "AbortError") return;
            console.warn("Hotel content unavailable:", err);
            break;
          }
        }
      } catch (e: any) {
        if (e?.name === "AbortError") return;
        setError(
          e instanceof ApiError
            ? ((e.body as any)?.message ?? `Server error (${e.status})`)
            : (e?.message ?? "Something went wrong."),
        );
        setLoading(false);
      }
    })();

    return () => ctrl.abort();
  }, [spKey]);

  const nights = nightsBetween(
    sp.get("checkIn") ?? "",
    sp.get("checkOut") ?? "",
  );
  const currency = hotels[0]?.currency ?? "USD";

  // ----- price slider bounds -----
  const ceiling = useMemo(() => {
    const max = Math.max(0, ...hotels.map((h) => h.perNight ?? 0));
    return Math.max(100, Math.ceil(max / 50) * 50);
  }, [hotels]);

  const lo = range ? Math.min(range[0], ceiling) : 0;
  const hi = range ? Math.min(range[1], ceiling) : ceiling;
  const priceActive = lo > 0 || hi < ceiling;

  // ----- sidebar options with counts -----
  const starCounts = useMemo(() => {
    const m: Record<number, number> = {};
    hotels.forEach((h) => {
      m[h.stars] = (m[h.stars] ?? 0) + 1;
    });
    return m;
  }, [hotels]);

  const typeOptions = useMemo(() => {
    const m = new Map<string, number>();
    hotels.forEach((h) => {
      if (h.type) m.set(h.type, (m.get(h.type) ?? 0) + 1);
    });
    return [...m.entries()].sort((a, b) => b[1] - a[1]);
  }, [hotels]);

  const facilityOptions = useMemo(
    () =>
      FACILITY_FILTERS.map((f) => ({
        ...f,
        count: hotels.filter((h) => h.facilityKeys.includes(f.key)).length,
      })).filter((f) => f.count > 0),
    [hotels],
  );

  // ----- filtered + sorted list -----
  const visible = useMemo(() => {
    const list = hotels.filter((h) => {
      const okStars = starSel.size === 0 || starSel.has(h.stars);
      const okType = typeSel.size === 0 || (!!h.type && typeSel.has(h.type));
      const okFac = [...facSel].every((k) => h.facilityKeys.includes(k));
      const okPrice =
        !priceActive ||
        (h.perNight != null &&
          h.perNight >= lo &&
          (hi >= ceiling || h.perNight <= hi));

      return okStars && okType && okFac && okPrice;
    });

    switch (sort) {
      case "priceLow":
        return [...list].sort(
          (a, b) => (a.perNight ?? Infinity) - (b.perNight ?? Infinity),
        );
      case "priceHigh":
        return [...list].sort((a, b) => (b.perNight ?? -1) - (a.perNight ?? -1));
      case "rating":
        return [...list].sort((a, b) => (b.rating ?? 0) - (a.rating ?? 0));
      case "stars":
        return [...list].sort((a, b) => b.stars - a.stars);
      default:
        return list;
    }
  }, [hotels, starSel, typeSel, facSel, priceActive, lo, hi, ceiling, sort]);

  const toggleWishlist = (code: number) =>
    setWishlist((prev) => toggle(prev, code));

  const viewHotel = (code: number) => router.push(`/hotels/${code}?${spKey}`);

  return (
    <div className={styles.root}>
      <div className={styles.layout}>
        {/* ---------------- Filter sidebar ---------------- */}
        <aside>
          <div className={styles.filters}>
            <div className={styles.filtersHead}>
              <h3>Filter Results</h3>
              <button type="button" className={styles.resetBtn} onClick={resetFilters}>
                Reset All
              </button>
            </div>

            <section className={styles.group}>
              <h4>Price per night ({currency})</h4>
              <PriceSlider
                ceiling={ceiling}
                lo={lo}
                hi={hi}
                onChange={(a, b) => setRange([a, b])}
              />
              <div className={styles.priceText}>
                {money(lo, currency)} - {money(hi, currency)}
                {hi >= ceiling ? "+" : ""}
              </div>
            </section>

            <section className={styles.group}>
              <h4>Star Rating</h4>
              {[5, 4, 3, 2, 1].map((s) => (
                <label key={s} className={styles.check}>
                  <input
                    type="checkbox"
                    checked={starSel.has(s)}
                    onChange={() => setStarSel((p) => toggle(p, s))}
                  />
                  <span className={styles.checkLabel}>
                    {s} Star{s > 1 ? "s" : ""}
                  </span>
                  <span className={styles.checkCount}>
                    {starCounts[s] ? starCounts[s].toLocaleString() : ""}
                  </span>
                </label>
              ))}
            </section>

            {typeOptions.length > 0 && (
              <section className={styles.group}>
                <h4>Property Type</h4>
                {typeOptions.map(([label, count]) => (
                  <label key={label} className={styles.check}>
                    <input
                      type="checkbox"
                      checked={typeSel.has(label)}
                      onChange={() => setTypeSel((p) => toggle(p, label))}
                    />
                    <span className={styles.checkLabel}>{label}</span>
                    <span className={styles.checkCount}>
                      {count.toLocaleString()}
                    </span>
                  </label>
                ))}
              </section>
            )}

            {facilityOptions.length > 0 && (
              <section className={styles.group}>
                <h4>Popular Facilities</h4>
                {facilityOptions.map((f) => (
                  <label key={f.key} className={styles.check}>
                    <input
                      type="checkbox"
                      checked={facSel.has(f.key)}
                      onChange={() => setFacSel((p) => toggle(p, f.key))}
                    />
                    <span className={styles.checkLabel}>{f.label}</span>
                    <span className={styles.checkCount}>
                      {f.count.toLocaleString()}
                    </span>
                  </label>
                ))}
              </section>
            )}
          </div>
        </aside>

        {/* ---------------- Results ---------------- */}
        <section>
          <p className={styles.count}>
            {loading
              ? "Searching hotels…"
              : `${visible.length.toLocaleString()} hotels found`}
          </p>

          <div className={styles.toolbar}>
            <label className={styles.sort}>
              <span>Sort by:</span>
              <select
                value={sort}
                onChange={(e) => setSort(e.target.value as Sort)}
              >
                <option value="recommended">Our Recommendations</option>
                <option value="priceLow">Price: Low to High</option>
                <option value="priceHigh">Price: High to Low</option>
                <option value="rating">Guest Rating: Highest</option>
                <option value="stars">Star Rating: Highest</option>
              </select>
            </label>

            <div className={styles.viewToggle}>
              <button type="button" className={`${styles.viewBtn} ${styles.viewBtnActive}`}>
                <List size={15} />
                List
              </button>
              <button type="button" className={styles.viewBtn}>
                <MapPin size={15} />
                Map
              </button>
            </div>
          </div>

          {loading && (
            <div className={styles.state}>
              <div className={styles.spinner} role="status" aria-label="Loading" />
              <p>Loading hotels...</p>
            </div>
          )}

          {!loading && error && (
            <div className={styles.error} role="alert">
              {error}
            </div>
          )}

          {!loading && !error && visible.length === 0 && (
            <div className={styles.state}>
              <h5>No hotels found</h5>
              <p>Try another destination or change your filters.</p>
            </div>
          )}

          {!loading &&
            !error &&
            visible.map((hotel) => {
              const location =
                [hotel.address, hotel.destination].filter(Boolean).join(", ") ||
                "Location unavailable";
              const liked = wishlist.has(hotel.code);

              return (
                <article key={hotel.code} className={styles.card}>
                  <button
                    type="button"
                    title="Save to Wishlist"
                    aria-label="Save to Wishlist"
                    className={styles.wishlist}
                    onClick={() => toggleWishlist(hotel.code)}
                  >
                    <Heart size={19} className={liked ? styles.heartOn : ""} />
                  </button>

                  <HotelImage src={hotel.images[0]} alt={hotel.name} />

                  <div className={styles.body}>
                    <div className={styles.titleRow}>
                      <div className={styles.titleCol}>
                        <button
                          type="button"
                          className={styles.title}
                          onClick={() => viewHotel(hotel.code)}
                        >
                          <b>{hotel.name}</b>
                        </button>

                        <div className={styles.stars}>
                          {Array.from({ length: hotel.stars }, (_, i) => (
                            <Star key={i} size={13} className={styles.star} />
                          ))}
                        </div>

                        <div className={styles.location}>
                          <MapPin size={13} />
                          <span>{location}</span>
                        </div>
                      </div>

                      {hotel.rating !== null && (
                        <div className={styles.rating}>
                          <span className={styles.ratingBox}>
                            {hotel.rating.toFixed(1)}
                          </span>
                          <span className={styles.ratingText}>
                            <b>{ratingLabel(hotel.rating)}</b>
                            {hotel.reviewCount !== null && (
                              <small>
                                {hotel.reviewCount.toLocaleString()} reviews
                              </small>
                            )}
                          </span>
                        </div>
                      )}
                    </div>

                    <p className={styles.desc}>
                      {hotel.description || "No description available."}
                    </p>

                    {hotel.amenities.length > 0 && (
                      <ul className={styles.amenities}>
  {hotel.amenities.map(({ label, Icon }, i) => (
    <li
      key={label}
      className={styles.amenity}
      style={{ "--i": i } as React.CSSProperties}
    >
      <span className={styles.amenityIcon}>
        <Icon size={14} />
      </span>
      {label}
    </li>
  ))}
</ul>
                    )}
                  </div>

                  <div className={styles.priceCol}>
                    {hotel.perNight !== null ? (
                      <>
                        <span className={styles.from}>From</span>
                        <strong
                          className={styles.price}
                          title={
                            hotel.price !== null
                              ? `${money(hotel.price, hotel.currency)} total for ${nights} night${nights > 1 ? "s" : ""}`
                              : undefined
                          }
                        >
                          {money(hotel.perNight, hotel.currency)}
                        </strong>
                        <span className={styles.per}>per night</span>
                      </>
                    ) : (
                      <span className={styles.per}>Price unavailable</span>
                    )}

                    <button
                      type="button"
                      className={styles.cta}
                      onClick={() => viewHotel(hotel.code)}
                    >
                      View Rooms
                      <ChevronRight size={14} />
                    </button>
                  </div>
                </article>
              );
            })}
        </section>
      </div>
    </div>
  );
}