"use client";

import Link from "next/link";
import { useSearchParams } from "next/navigation";
import { Calendar, MapPin, User } from "lucide-react";
import styles from "./search-summary.module.css";

function fmtDate(value: string | null) {
  if (!value) return "Select date";
  const [y, m, d] = value.split("-").map(Number);
  if (!y || !m || !d) return value;
  return new Date(y, m - 1, d).toLocaleDateString("en-GB", {
    day: "numeric",
    month: "short",
    year: "numeric",
  });
}

const plural = (n: number, one: string, many = `${one}s`) =>
  `${n} ${n === 1 ? one : many}`;

/** Change this if your search form lives on another route. */
export default function SearchSummary({ modifyHref = "/" }: { modifyHref?: string }) {
  const sp = useSearchParams();

  const destination =
    sp.get("term") || sp.get("destination") || "Selected location";
  const adults = Math.max(1, Number(sp.get("adults") ?? 2));
  const children = Math.max(0, Number(sp.get("children") ?? 0));
  const rooms = Math.max(1, Number(sp.get("rooms") ?? 1));

  const guests = [
    plural(adults, "Adult"),
    children > 0 ? plural(children, "Child", "Children") : "",
    plural(rooms, "Room"),
  ]
    .filter(Boolean)
    .join(", ");

  const query = sp.toString();

  return (
    <div className={styles.wrap}>
      <div className={styles.bar}>
        <div className={styles.field}>
          <MapPin size={18} className={styles.icon} />
          <span>{destination}</span>
        </div>

        <div className={styles.field}>
          <Calendar size={18} className={styles.icon} />
          <span>
            {fmtDate(sp.get("checkIn"))} – {fmtDate(sp.get("checkOut"))}
          </span>
        </div>

        <div className={styles.field}>
          <User size={18} className={styles.icon} />
          <span>{guests}</span>
        </div>

        <Link
          href={query ? `${modifyHref}?${query}` : modifyHref}
          className={styles.btn}
        >
          Modify Search
        </Link>
      </div>
    </div>
  );
}