export type Coords = { lat: number; lng: number };

const KEY = process.env.NEXT_PUBLIC_GOOGLE_MAPS_API_KEY;

/** Coordinates for a typed place name (e.g. "Turkey"). Returns null on failure. */
export async function geocodeText(
  text: string,
  signal?: AbortSignal,
): Promise<Coords | null> {
  if (!KEY || !text.trim()) return null;
  try {
    const qs = new URLSearchParams({ address: text, key: KEY });
    const res = await fetch(
      `https://maps.googleapis.com/maps/api/geocode/json?${qs}`,
      { signal },
    );
    const json = await res.json();
    const loc = json?.results?.[0]?.geometry?.location;
    return loc ? { lat: Number(loc.lat), lng: Number(loc.lng) } : null;
  } catch {
    return null;
  }
}