/**
 * Hotels API client.
 *
 * .env.local:
 *   NEXT_PUBLIC_API_URL=http://localhost:5000/api/v1
 */

export interface HotelSearchPayload {
  stay: {
    checkIn: string;
    checkOut: string;
    shiftDays: number;
    allowOnlyShift: boolean;
  };
  occupancies: {
    rooms: number;
    adults: number;
    children: number;
    paxes: { type: "CH"; age: number }[];
  }[];
  geolocation: {
    longitude: string;
    latitude: string;
    radius: string;
    unit: string;
  };
}

const API_BASE = (
  process.env.NEXT_PUBLIC_API_URL ?? "http://localhost:3000/api/v1"
).replace(/\/+$/, "");

export const ENDPOINTS = {
  availability: "/hotels/availability",
  details: "/hotels/details",
} as const;

/** Thrown for non-2xx responses. `body` holds the parsed error response. */
export class ApiError extends Error {
  status: number;
  body: unknown;

  constructor(status: number, body: unknown) {
    super(`Request failed with status ${status}`);
    this.name = "ApiError";
    this.status = status;
    this.body = body;
  }
}

async function post<T = any>(
  path: string,
  body: unknown,
  signal?: AbortSignal,
): Promise<T> {
  const response = await fetch(`${API_BASE}${path}`, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      Accept: "application/json",
    },
    body: JSON.stringify(body),
    signal,
  });

  const text = await response.text();

  let parsed: unknown = text;
  try {
    parsed = text ? JSON.parse(text) : null;
  } catch {
    /* not JSON - keep the raw text */
  }

  if (!response.ok) throw new ApiError(response.status, parsed);

  return parsed as T;
}

/** POST /hotels/availability */
export function getHotels(payload: HotelSearchPayload, signal?: AbortSignal) {
  return post(ENDPOINTS.availability, payload, signal);
}

/**
 * Hotel content (images, description, address, facilities) for hotel codes.
 * POST /hotels/details  { hotelCodes: [..], language: "ENG" }
 */
export function getHotelDetails(
  codes: number[],
  signal?: AbortSignal,
  language = "ENG",
) {
  return post(
    ENDPOINTS.details,
    { hotelCodes: codes, language, useSecondaryLanguage: false },
    signal,
  );
}